function reorderedPowerOf2(n) {
  const left = new Array(10).fill(0);
  const digits = String(n);
  for (const ch of digits) left[Number(ch)]++;
  const isPower = (x) => {
    while (x % 2 === 0) x /= 2;
    return x === 1;
  };
  // Try every distinct arrangement of the digits that does not start with 0.
  const build = (value, placed) => {
    if (placed === digits.length) return isPower(value);
    for (let d = 0; d <= 9; d++) {
      if (left[d] === 0 || (placed === 0 && d === 0)) continue;
      left[d]--;
      const found = build(value * 10 + d, placed + 1);
      left[d]++;
      if (found) return true;
    }
    return false;
  };
  return build(0, 0);
}

