function generate(rand, size) {
  const r = rand();
  if (r < 0.5) {
    // Shuffle the digits of a power of two, so that the answer is true.
    const maxExp = size === 'large' ? 29 : 16;
    const minExp = size === 'large' ? 20 : 0;
    const exp = minExp + Math.floor(rand() * (maxExp - minExp + 1));
    const digits = String(2 ** exp).split('');
    for (;;) {
      for (let i = digits.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [digits[i], digits[j]] = [digits[j], digits[i]]; }
      if (digits[0] !== '0') return [Number(digits.join(''))];
    }
  }
  if (r < 0.75) {
    // Change one digit of a power of two: usually false, sometimes still true.
    const exp = Math.floor(rand() * (size === 'large' ? 30 : 17));
    const digits = String(2 ** exp).split('');
    const at = Math.floor(rand() * digits.length);
    digits[at] = String(at === 0 ? 1 + Math.floor(rand() * 9) : Math.floor(rand() * 10));
    return [Number(digits.join(''))];
  }
  const limit = size === 'large' ? 1000000000 : 100000;
  return [1 + Math.floor(rand() * limit)];
}
